import{_ as r,a0 as e,w as a,s as p,ao as I,I as i,x as l,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"OSI 模型是什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"OSI 模型是什麼？ | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OSI 模型是什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OSI 模型是什麼？ | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20210511 What is the OSI model","title":"OSI 模型是什麼？","tag":"202207","desc":""},"relativePath":"202207/20210511 What is the OSI model.md","filePath":"[post].md"}'),d={name:"202207/20210511 What is the OSI model.md"};function P(S,t,u,T,O,m){const o=e("Link");return a(),p("div",null,[t[26]||(t[26]=I('<h1 id="osi-模型是什麼" tabindex="-1">OSI 模型是什麼？ <a class="header-anchor" href="#osi-模型是什麼" aria-label="Permalink to “OSI 模型是什麼？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/02/153620k7nwc6nn2b6n6p2c.jpg" alt=""></p><p>（LCTT 校注：作者原文已經大篇幅進行了修訂更新，本文據之前的版本翻譯。）</p><p>今天我在推特上發佈了一些關於 OSI 模型如何與 TCP/IP 工作原理的實際表現不相符的觀點，這讓我思考——OSI 模型到底是什麼？通過閲讀推特上的一些回覆發現，似乎至少存在三種不同的思考方式：</p><ol><li>TCP/IP 工作原理的字面描述</li><li>一個可以用來描述和比較很多不同的網絡協議的抽象模型</li><li>對 1980 年代的一些計算機網絡協議的字面描述，這些協議如今大多已不再使用</li></ol><p>在這篇文章中，我不打算試圖爭辯以上哪一個才是“真正”的 OSI 模型——似乎不同的人以所有這些方式思考它。這不重要。</p><h3 id="osi-模型有七層" tabindex="-1">OSI 模型有七層 <a class="header-anchor" href="#osi-模型有七層" aria-label="Permalink to “OSI 模型有七層”">​</a></h3><p>在我們討論 OSI 模型的含義之前，讓我們大致地討論一下它是什麼。它是一個抽象模型，用於描述網絡如何在七個編號的層上工作：</p><ul><li>第一層：物理層</li><li>第二層：數據鏈路層</li><li>第三層：網絡層</li><li>第四層：傳輸層</li><li>第五層：會話層</li><li>第六層：表示層</li><li>第七層：應用層</li></ul><p>我不會再費時地去解釋每一層的含義，網上有上千種解釋可供查詢。</p><h3 id="osi-模型-tcp-ip-工作原理的字面描述" tabindex="-1">OSI 模型：TCP/IP 工作原理的字面描述 <a class="header-anchor" href="#osi-模型-tcp-ip-工作原理的字面描述" aria-label="Permalink to “OSI 模型：TCP/IP 工作原理的字面描述”">​</a></h3><p>首先，我想談談人們在實踐中使用 OSI 模型的一種常見方式：作為對 TCP/IP 工作原理的字面描述。OSI 模型的某些層非常容易映射到 TCP/IP：</p><ul><li>第二層對應以太網</li><li>第三層對應 IP</li><li>第四層對應 TCP 或 UDP（或 ICMP 等）</li><li>第七層對應 TCP 或 UDP 包內的任何內容（例如 DNS 查詢）</li></ul><p>這種映射對第二、三、四層很有意義——TCP 數據包有三個<ruby>標頭<rt>header</rt></ruby>對應於這三個層（以太網標頭、IP 標頭和 TCP 標頭）。</p><p>用數字來描述 TCP 數據包中的不同標頭非常有用——如果你説“第二層”，很顯然它位於第三層“下方”，因為二比三小。</p><p>“OSI 模型作為字面描述”的古怪之處在於，第五層和第六層並不真正對應於 TCP/IP 中的任何內容——我聽説過很多關於第五層或第六層可能是什麼的不同解釋（你可以説第五層是 TLS 或其他東西！）但它們沒有像第二、三、四層那樣“每一層在 TCP 數據包中都有相應的標頭”這樣的明確對應關係。</p><p>此外，TCP/IP 的某些部分即使在第二層到第四層也不能很好地適應 OSI 模型——例如，哪一層是 ARP 數據包？ARP 數據包發送一些帶有以太網標頭的數據，這是否意味着它們是第三層？或是第二層？列出不同 OSI 層的維基百科文章將其歸類為“第 2.5 層”，這並不令人滿意。</p><p>因為 OSI 模型有時用於教授 TCP/IP，若搞不清楚它的哪些部分可以映射到 TCP/IP，而哪些部分不能，則會令人困惑。這才是真的問題。</p><h3 id="osi-模型-用於比較網絡協議的一個抽象" tabindex="-1">OSI 模型：用於比較網絡協議的一個抽象 <a class="header-anchor" href="#osi-模型-用於比較網絡協議的一個抽象" aria-label="Permalink to “OSI 模型：用於比較網絡協議的一個抽象”">​</a></h3>',19)),i("p",null,[t[1]||(t[1]=l("我聽説過的另一種關於 OSI 的思考方式是，它是一種抽象，可以用來在許多不同的網絡協議之間進行類比。例如，如果你想了解藍牙協議的工作原理，也許你可以使用 OSI 模型來幫助你——這是我在 ",-1)),s(o,{href:"https://flylib.com/books/en/4.215.1.116/1/"},{default:n(()=>[...t[0]||(t[0]=[l("這個網頁",-1)])]),_:1}),t[2]||(t[2]=l(" 上找到的一張圖表，顯示了藍牙協議如何適配 OSI 模型。",-1))]),t[27]||(t[27]=i("p",null,[i("img",{src:"https://jvns.ca/images/bluetooth.gif",alt:""})],-1)),i("p",null,[t[4]||(t[4]=l("另一個例子是，",-1)),s(o,{href:"https://en.wikipedia.org/wiki/List_of_network_protocols_(OSI_model)"},{default:n(()=>[...t[3]||(t[3]=[l("這篇維基百科文章",-1)])]),_:1}),t[5]||(t[5]=l(" 有一個 OSI 層列表，詳細劃分了哪些特定的網絡協議對應於這些 OSI 層。",-1))]),t[28]||(t[28]=i("h3",{id:"osi-模型-一些過時協議的字面描述",tabindex:"-1"},[l("OSI 模型：一些過時協議的字面描述 "),i("a",{class:"header-anchor",href:"#osi-模型-一些過時協議的字面描述","aria-label":"Permalink to “OSI 模型：一些過時協議的字面描述”"},"​")],-1)),i("p",null,[t[8]||(t[8]=l("維基百科上的一些非常簡短的研究表明，除了對這七層的抽象描述之外，OSI 模型還包含了 ",-1)),s(o,{href:"https://en.wikipedia.org/wiki/OSI_protocols"},{default:n(()=>[...t[6]||(t[6]=[l("一組實現這些層的特定協議",-1)])]),_:1}),t[9]||(t[9]=l("。顯然，這發生在 70 年代和 80 年代的 ",-1)),s(o,{href:"https://en.wikipedia.org/wiki/Protocol_Wars"},{default:n(()=>[...t[7]||(t[7]=[l("協議戰爭",-1)])]),_:1}),t[10]||(t[10]=l(" 時期，OSI 模型失敗了，TCP/IP 則取得了勝利。",-1))]),t[29]||(t[29]=i("p",null,[l("這就解釋了為什麼 OSI 模型無法與 TCP/IP 很好地對應，因為如果當時“獲勝”的是 OSI 協議，那麼 OSI 模型 "),i("em",null,"將"),l(" 完全對應於互聯網網絡的實際工作方式。")],-1)),t[30]||(t[30]=i("h3",{id:"結語",tabindex:"-1"},[l("結語 "),i("a",{class:"header-anchor",href:"#結語","aria-label":"Permalink to “結語”"},"​")],-1)),t[31]||(t[31]=i("p",null,"我寫這篇文章的初衷是，當我最初學習 OSI 模型時，我發現它非常令人困惑（所有這些層是什麼？它們是真實存在的嗎？這是網絡的實際工作原理嗎？發生了什麼？）我希望有人告訴我這個只使用 TCP/IP 網絡協議的人，只需瞭解 OSI 模型第二、三、四和七層與 TCP/IP 的關係，然後忽略它的所有其他內容即可。所以我希望這篇文章對某些人能有所幫助！",-1)),t[32]||(t[32]=i("hr",null,null,-1)),i("p",null,[t[12]||(t[12]=l("via: ",-1)),s(o,{href:"https://jvns.ca/blog/2021/05/11/what-s-the-osi-model-/"},{default:n(()=>[...t[11]||(t[11]=[l("https://jvns.ca/blog/2021/05/11/what-s-the-osi-model-/",-1)])]),_:1})]),i("p",null,[t[17]||(t[17]=l("作者：",-1)),s(o,{href:"https://jvns.ca/"},{default:n(()=>[...t[13]||(t[13]=[l("Julia Evans",-1)])]),_:1}),t[18]||(t[18]=l(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[14]||(t[14]=[l("lujun9972",-1)])]),_:1}),t[19]||(t[19]=l(" 譯者：",-1)),s(o,{href:"https://github.com/hanszhao80"},{default:n(()=>[...t[15]||(t[15]=[l("hanszhao80",-1)])]),_:1}),t[20]||(t[20]=l(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[16]||(t[16]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[23]||(t[23]=l("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[21]||(t[21]=[l("LCTT",-1)])]),_:1}),t[24]||(t[24]=l(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:n(()=>[...t[22]||(t[22]=[l("Linux中國",-1)])]),_:1}),t[25]||(t[25]=l(" 榮譽推出",-1))])])}const g=r(d,[["render",P]]);export{b as __pageData,g as default};
